    IF NOT EXISTS (SELECT 1 FROM civic_data_promotions p JOIN civic_data_candidates c ON c.id=p.current_version_id
      WHERE p.record_class=origin->>'recordClass' AND p.scope=origin->>'oldScope' AND p.current_version_id=origin->>'oldId'
        AND c.state='PROMOTED' AND p.payload=c.candidate->'readModel' AND p.validation_receipt=c.validation_receipt)
    THEN RAISE EXCEPTION 'BL-30 obsolete authority changed: %',origin->>'oldScope'; END IF;
    IF jsonb_array_length(origin->'replacements')=0 THEN RAISE EXCEPTION 'BL-30 state replacement missing'; END IF;
    FOR replacement IN SELECT value FROM jsonb_array_elements(origin->'replacements') LOOP
      IF NOT EXISTS (SELECT 1 FROM civic_data_candidates c JOIN civic_data_promotions p ON p.record_class=c.record_class AND p.scope=c.scope
        WHERE c.id=replacement->>'id' AND c.scope=replacement->>'scope' AND c.record_class=replacement->>'recordClass'
          AND c.state='PROMOTED' AND c.validation_receipt->>'decision'='GOOD')
      THEN RAISE EXCEPTION 'BL-30 state replacement not serving: %',replacement->>'scope'; END IF;
    END LOOP;
    INSERT INTO bl30_retire VALUES(origin->>'recordClass',origin->>'oldScope',origin->>'oldId');
